144: function normalizeHex(value, { allowShort = true } = {}) {
145:   if (typeof value !== 'string') return null;
146:   let hex = value.trim().replace(/^#/, '');
147:   if (!/^[0-9a-f]+$/i.test(hex)) return null;
148:   if (allowShort && hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
149:   if (hex.length !== 6) return null;
150:   return `#${hex.toUpperCase()}`;
151: }
152: 
153: function hexToInt(hex) { return parseInt(hex.slice(1), 16); }
