286:     const r1 = 74, r2 = i % 2 === 0 ? 63 : 68;
287:     const line = document.createElementNS(NS, 'line');
288:     line.setAttribute('x1', 100 + Math.cos(a) * r1);
289:     line.setAttribute('y1', 108 + Math.sin(a) * r1);
290:     line.setAttribute('x2', 100 + Math.cos(a) * r2);
291:     line.setAttribute('y2', 108 + Math.sin(a) * r2);
292:     dom.speedoTicks.appendChild(line);
293:   }
294: }
