972: /* ═══════════════════════════════════════════════════════════════════
973:    Race setup
974:    ═══════════════════════════════════════════════════════════════════ */
975: const GRID_GAP = 11;
976: const GRID_FIRST = 10;
977: const GRID_STAGGER = 5.2;
978: const GRID_LATERAL = 2.75;
979: 
980: // Proper staggered grid: two cars per row, one either side of the centre line,
981: // with the right-hand car a few metres further back. Slot order is decided by
982: // the caller, so grid position and driver pace stay independent.
983: function gridDistance(slot) {
984:   const row = Math.floor(slot / 2);
985:   const col = slot % 2;
986:   return -(GRID_FIRST + row * GRID_GAP + col * GRID_STAGGER);
987: }
988: 
989: function gridPose(slot) {
990:   const dist = gridDistance(slot);
991:   const lateral = (slot % 2 === 0 ? -1 : 1) * GRID_LATERAL;
992:   const s = sampleAtDistance(race.track, dist);
993:   return {
994:     x: s.x + s.nx * lateral,
995:     z: s.z + s.nz * lateral,
996:     yaw: Math.atan2(s.tx, s.tz),
997:     lateral,
998:     dist,
999:     s
1000:   };
1001: }
