1850: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1851:   const N = track.N;
1852:   let best = -1;
1853:   let bestD = Infinity;
1854:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1855:     const span = Math.max(6, Math.round(windowMeters / track.step));
1856:     for (let k = -span; k <= span; k++) {
1857:       const i = (hint + k + N) % N;
1858:       const s = track.samples[i];
1859:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1860:       if (d < bestD) { bestD = d; best = i; }
1861:     }
1862:     // If the car is well off the road (or has been recovered), fall back to the
1863:     // spatial lookup so it can always find its way back to the nearest asphalt.
1864:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1865:       const global = race.locator.nearest(x, z);
1866:       const d = global.dist * global.dist;
1867:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1868:     }
1869:   }
1870:   if (best < 0) {
1871:     const global = race.locator.nearest(x, z);
1872:     best = global.index >= 0 ? global.index : 0;
1873:     bestD = global.dist * global.dist;
1874:   }
1875:   return { index: best, dist: Math.sqrt(bestD) };
1876: }
