import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const configFile = join(runtime, 'linux.json');
const config = JSON.parse(readFileSync(configFile, 'utf8'));
if (!process.env.DISPLAY) {
  try { process.env.DISPLAY = `:${readFileSync(join(runtime, 'display'), 'utf8').trim()}`; } catch {}
}
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
launchOptions.executablePath = '/opt/google/chrome/chrome';
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('console', m => console.log('[console]', m.type(), m.text()));
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.goto('http://localhost:3000/?demo=race&track=0&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race, null, { timeout: 30000 });
await page.waitForTimeout(1000);

const result = await page.evaluate(async () => {
  const a = window.__apex;
  a.setDemoInput({ gas: false, brake: false, left: false, right: false });
  const log = [];
  const race = a.race;
  race.totalLaps = 3;
  // speed up physics by ticking manually
  const start = race.time;
  let lastLap = -1;
  let lastPhase = '';
  for (let i = 0; i < 60 * 240; i++) {
    const p = race.player;
    // simple autopilot steering toward a point 16m ahead on the centerline
    const L = race.track.length;
    const s = ((p.progressDist % L) + L) % L;
    const look = (s + 18) % L;
    const idx = Math.floor(look / race.track.step) % race.track.N;
    const t = race.track.samples[idx];
    const dx = t.x - p.pos.x, dz = t.z - p.pos.z;
    const heading = Math.atan2(dx, dz);
    let err = heading - p.yaw;
    while (err > Math.PI) err -= Math.PI * 2;
    while (err < -Math.PI) err += Math.PI * 2;
    a.setDemoInput({ left: err > 0.025, right: err < -0.025 });
    a.tick(1 / 60);
    if (p.lapsCompleted !== lastLap) {
      lastLap = p.lapsCompleted;
      log.push({ t: Math.round(race.time), lap: lastLap, phase: race.pit.phase, progress: Math.round(p.progressDist), L: Math.round(race.track.length) });
    }
    if (race.pit.phase !== lastPhase) {
      lastPhase = race.pit.phase;
      log.push({ t: Math.round(race.time), phase: lastPhase, laps: p.lapsCompleted, progress: Math.round(p.progressDist), speed: Math.round(p.vLong * 3.6), route: Math.round(race.pit.routeProgress) });
    }
    if (race.state === 'finished') { log.push({ finished: true, t: Math.round(race.time) }); break; }
  }
  return { log, state: race.state, laps: race.player.lapsCompleted, phase: race.pit.phase, progress: race.player.progressDist, len: race.track.length, pos: race.player.pos };
});
console.log(JSON.stringify(result, null, 2));
await browser.close();

