import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (!process.env.DISPLAY) { try { process.env.DISPLAY = `:${readFileSync(join(runtime, 'display'), 'utf8').trim()}`; } catch {} }
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
launchOptions.executablePath = '/opt/google/chrome/chrome';
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex, null, { timeout: 30000 });
await page.waitForTimeout(700);

const all = [];
for (const n of [1, 2, 3, 4, 5, 10]) {
  const out = await page.evaluate(async (n) => {
    const a = window.__apex;
    document.querySelector('#setup-laps').value = String(n);
    await a.beginBuild(a.demoPoints(0), { instant: true });
    const race = a.race;
    a.startRaceNow();
    a.setDemoInput({ gas: false, brake: false, left: false, right: false });
    const events = [];
    let lastLap = -1;
    let lastPhase = '';
    let lastStops = -1;
    let callAtLap = null;
    for (let i = 0; i < 60 * 420; i++) {
      const p = race.player;
      const L = race.track.length;
      const s = ((p.progressDist % L) + L) % L;
      const look = (s + 18) % L;
      const idx = Math.floor(look / race.track.step) % race.track.N;
      const t = race.track.samples[idx];
      let err = Math.atan2(t.x - p.pos.x, t.z - p.pos.z) - p.yaw;
      while (err > Math.PI) err -= Math.PI * 2;
      while (err < -Math.PI) err += Math.PI * 2;
      a.setDemoInput({ left: err > 0.025, right: err < -0.025 });
      a.tick(1 / 60);
      if (race.pit.phase !== lastPhase) {
        if (race.pit.phase === 'called') callAtLap = p.lapsCompleted + 1;
        events.push({ phase: race.pit.phase, lapStart: p.lapsCompleted + 1, t: Math.round(race.time / 1000), speed: Math.round(p.vLong * 3.6), tyre: Math.round(p.tyreLife * 100) });
        lastPhase = race.pit.phase;
      }
      if (race.pit.stops !== lastStops) {
        events.push({ stops: race.pit.stops, tyre: Math.round(p.tyreLife * 100), lapStart: p.lapsCompleted + 1, t: Math.round(race.time / 1000) });
        lastStops = race.pit.stops;
      }
      if (p.lapsCompleted !== lastLap) {
        lastLap = p.lapsCompleted;
        if (p.lapsCompleted > 0 && p.lapsCompleted < race.totalLaps) {
          events.push({ lapDone: p.lapsCompleted, t: Math.round(race.time / 1000) });
        }
      }
      if (race.state === 'finished') break;
    }
    return { totalLaps: race.totalLaps, callAfterLaps: race.pit.callAfterLaps, callAtLap, stops: race.pit.stops, state: race.state, laps: race.player.lapsCompleted, tyre: Math.round(race.player.tyreLife * 100), events };
  }, n);
  console.log(`--- ${n} LAPS ---`);
  console.log(JSON.stringify(out));
  all.push(out);
}
await browser.close();

