import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const out = process.env.OUT || '/tmp/opencode/pit.png';
const mode = process.env.MODE || 'over';

const browser = await chromium.launch({ headless: false, executablePath: '/usr/bin/google-chrome', args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERR', m.text()); });
page.on('pageerror', e => console.log('PAGE ERR', e.message));
await page.goto('http://127.0.0.1:3000/?demo=race&go=1', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__apex?.race?.world, null, { timeout: 60000 });
await page.waitForTimeout(1200);
await page.evaluate(({ mode }) => {
  const r = window.__apex.race;
  r.state = 'paused';
  const route = r.world.pitRoute;
  const box = r.world.playerPitBox;
  const cp = route[38];
  const tx = cp.tx, tz = cp.tz, nx = cp.tz, nz = -cp.tx;
  const cam = r.camera;
  if (mode === 'over') {
    cam.position.set(cp.x + nx * 45 + tx * 5, 34, cp.z + nz * 45 + tz * 5);
    cam.lookAt(cp.x + nx * 8, 2, cp.z + nz * 8);
  } else if (mode === 'side') {
    cam.position.set(cp.x + nx * 26 + tx * 28, 7, cp.z + nz * 26 + tz * 28);
    cam.lookAt(cp.x + nx * 8, 3, cp.z + nz * 8);
  } else if (mode === 'approach') {
    cam.position.set(cp.x - tx * 30 - nx * 2, 4.5, cp.z - tz * 30 - nz * 2);
    cam.lookAt(cp.x + tx * 20, 2.2, cp.z + tz * 20);
  } else if (mode === 'track') {
    cam.position.set(cp.x - nx * 20 - tx * 15, 12, cp.z - nz * 20 - tz * 15);
    cam.lookAt(cp.x + nx * 10, 2, cp.z + nz * 10);
  }
  cam.fov = 55;
  cam.updateProjectionMatrix();
  window.__shot = { cp, box, route0: route[0], route76: route[76], len: r.world.pitRouteLength };
}, { mode });
await page.waitForTimeout(400);
await page.screenshot({ path: out });
console.log(await page.evaluate(() => window.__shot));
await browser.close();

