content.text:
Now add helper functions for AI pit and pit path. Best place after `pitMetrics` or near `updatePitPhysics`. Let's design carefully.

Add:
```js
const PIT_LIMITER = 24;
const PIT_BOX_OFFSET = ... race.world.pitBoxLateral ?? 3.6;

function pitBoxOffset(routeProgress, boxRoute, phase) {
  const offset = race.world.pitBoxLateral ?? 3.6;
  if (phase === 'driving-in' || phase === 'in') {
    const remaining = boxRoute - routeProgress;
    if (remaining > 34) return 0;
    if (remaining < 0) return offset;
    const t = smoothstep(34, 2, remaining); // 0 at 34, 1 at 2
    return offset * t;
  }
  if (phase === 'driving-out' || phase === 'out') {
    const travelled = routeProgress - boxRoute;
    if (travelled <= 0) return offset;
    if (travelled > 34) return 0;
    return offset * (1 - smoothstep(0, 34, travelled));
  }
  return 0;
}
```
At service, pit.routeProgress = boxRoute, offset should be full; helper for 'service' returns 0 unless handled. Pose uses box directly.

`pitPathPoint(distance, phase, boxRoute)`:
```js
function pitPathPoint(distance, phase, boxRoute) {
