await page.goto('http://127.0.0.1:3000/?demo=race&go=1', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__apex?.race?.world, null, { timeout: 60000 });
await page.waitForTimeout(800);
const info = await page.evaluate(() => {
  const r = window.__apex.race;
  const scene = r.world.scene;
  const signs = [];
  scene.traverse(o => {
    if (o.isMesh && o.geometry?.parameters?.width === 9.3 && o.geometry?.parameters?.height === 1.18) {
      const e = o.matrixWorld.elements;
      const px = e[12], py = e[13], pz = e[14];
      const nx = e[8], ny = e[9], nz = e[10];
      signs.push({ px, py, pz, nx, ny, nz });
    }
  });
  const box = r.world.playerPitBox;
  // nearest route point to first sign
  function nearest(route, x, z) { let bi=0,bd=1e9; for(let i=0;i<route.length;i++){const d=Math.hypot(route[i].x-x,route[i].z-z); if(d<bd){bd=d;bi=i;}} return {i:bi,d:bd}; }
  const out = signs.map(s => {
    const n = nearest(r.world.pitRoute, s.px, s.pz);
    const lane = r.world.pitRoute[n.i];
    const toLane = { x: lane.x - s.px, z: lane.z - s.pz };
    const dot = toLane.x * s.nx + toLane.z * s.nz;
    return { ...s, nearestRoute: n, lane, toLane, dot };
  });
  return { box, signs: out.slice(0,3) };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

