import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const URL = 'http://127.0.0.1:3001/?demo=race&go=1&track=0';
const browser = await chromium.launch({ headless: false, executablePath: '/usr/bin/google-chrome', args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
await page.goto(URL, { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__apex?.race?.world, null, { timeout: 60000 });
await page.waitForTimeout(600);

const setup = await page.evaluate(() => {
  const r = window.__apex.race;
  const L = r.track.length;
  const entryDist = L - 190;
  const forced = [];
  for (let i = 0; i < 3; i++) {
    const a = r.ai[i];
    a.pit.phase = 'scheduled';
    a.pit.entryLap = 1;
    a.pit.entryDist = entryDist;
    a.pit.stops = 0;
    a.pit.routeProgress = 0;
    a.dist = entryDist - (95 + i * 26);
    a.speed = 48;
    a.lateral = 0;
    forced.push({ name: a.name, dist: a.dist, box: a.pitBox.routeProgress });
  }
  return { L, entryDist, forced, playerBox: r.world.playerPitBox, pitBoxDistance: r.world.pitBoxDistance };
});
console.log('SETUP', JSON.stringify(setup));

async function poll(ms, label) {
  const t0 = Date.now();
  const seen = {};
  while (Date.now() - t0 < ms) {
    const s = await page.evaluate(() => {
      const r = window.__apex.race;
      return r.ai.slice(0, 3).map(a => ({
        n: a.name, ph: a.pit.phase, rp: +a.pit.routeProgress.toFixed(1),
        d: +a.dist.toFixed(1), sp: +a.pit.speed.toFixed(1),
        x: +a.pit.x.toFixed(1), z: +a.pit.z.toFixed(1)
      }));
    });
    for (const a of s) {
      if (seen[a.n] !== a.ph) {
        seen[a.n] = a.ph;
        console.log(`[${label}] ${((Date.now() - t0) / 1000).toFixed(1)}s`, JSON.stringify(a));
      }
    }
    if (Object.values(seen).every(p => p === 'done')) break;
    await page.waitForTimeout(400);
  }
  return seen;
}

