import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: false, executablePath: '/usr/bin/google-chrome', args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const ctx = await browser.newContext({ viewport: { width: 1200, height: 800 } });
const page = await ctx.newPage();
page.on('pageerror', e => console.log('PAGE ERR', e.message));
await page.goto('http://127.0.0.1:3001/?demo=race&go=1&track=0', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__apex?.race?.world, null, { timeout: 60000 });
await page.waitForTimeout(800);

const info = await page.evaluate(() => {
  const r = window.__apex.race;
  r.state = 'paused';
  const box = r.world.playerPitBox;
  const route = r.world.pitRoute;
  const p = route[37];
  const tx = p.tx, tz = p.tz, nx = p.tz, nz = -p.tx;
  const cam = r.camera;
  // Stand on the pit box looking straight into the garage.
  cam.position.set(p.x - tx * 1.2, 2.4, p.z - tz * 1.2);
  cam.lookAt(p.x + nx * 14, 2.6, p.z + nz * 14);
  cam.fov = 50;
  cam.updateProjectionMatrix();
  const panels = [];
  r.world.garages[4].traverse(o => {
    if (o.isMesh && o.material?.map && o.material?.type === 'MeshBasicMaterial') {
      panels.push({ w: o.geometry.parameters?.width, h: o.geometry.parameters?.height, y: +o.position.y.toFixed(2), z: +o.position.z.toFixed(2), visible: o.visible });
    }
  });
  return { box, panels };
});
console.log(JSON.stringify(info, null, 2));
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/pit-interior.png' });
await browser.close();

