  // Park one car at its box for service.
  a0.pit.phase = 'service';
  a0.pit.routeProgress = a0.pitBox.routeProgress;
  a0.pit.serviceTimer = 60;
  a0.pit.speed = 0;
  a0.dist = a0.pit.entryDist + a0.pit.routeProgress;
  // Send another car down the through-lane to a box beyond the player's.
  a5.pit.phase = 'in';
  a5.pit.routeProgress = 150;
  a5.pit.speed = 24;
  a5.dist = a5.pit.entryDist + 150;
  // Player mid-service at the APEX box.
  r.pit.phase = 'servicing';
  r.pit.routeProgress = r.world.pitBoxDistance;
  r.pit.serviceTimer = 60;
  const p = r.player;
  const box = r.world.playerPitBox;
  p.pos.x = box.x; p.pos.z = box.z; p.yaw = box.yaw;
  p.vel.x = 0; p.vel.z = 0; p.vLong = 0; p.vLat = 0;
